import {getUserList,userRemove} from "@/api/terminal";
import moment from "moment";
export default {
  data() {
    return {
      // 搜索相关
      searchForm: {
        ip: undefined,
        name: undefined,
        status: undefined,
        current: 1,
        size: 20,
      },
      // 表格相关
      dataList: [],
      loading: false,
      tableHeight: undefined,
      total: 0,
      deviceStatusList:[{
        label: '1',
        value: '在线'
      },{
        label: '0',
        value: '离线'
      }],
    };
  },
  mounted(){
    // 设置页面元素高度
    this.setPageContentHeight()
    // 设置表格高度
    this.setTableHeight()
    //加载数据
    this.onLoad();
  },
  methods: {
    // 设置表格高度
    setTableHeight() {
      let pageBody = document.getElementsByClassName('page_body')
      this.tableHeight = pageBody[0].offsetHeight - 61 - 47 + 'px'
    },
    handleQuery() {
      this.searchForm.current = 1
      this.onLoad();
    },
    handleDeleteOne(id) {
      //删除按钮
      let ids = id;
      this.handleDeleteConfirm(ids);
    },
    handleDeleteConfirm(ids) {
      this.$confirm("点击确认将永久删除数据且无法恢复，请谨慎选择。", "确定将选择数据删除?", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning"
      })
        .then(() => {
          return userRemove(ids);
        })
        .then(() => {
          this.onLoad();
          this.$message({
            type: "success",
            message: "操作成功!"
          });
        });
    },
    searchReset() {
      //重置按钮
      this.searchForm = {
        ip: undefined,
        status: undefined,
        current: 1,
        size: 20,
      }
      this.onLoad();
    },
    onLoad() {
      //加载数据
      this.loading = true;
      console.log('this.searchForm', this.searchForm);
      getUserList(this.searchForm).then(res => {
        const data = res.data;
        this.total = data.total;
        this.dataList = data.records.map(item => {
          // 格式化timeList中的时间
          if (item.timeList && item.timeList.length > 0) {
            item.timeList = item.timeList.map(timeItem => {
              return {
                ...timeItem,
                loginBeginTime: timeItem.loginBeginTime ? moment(timeItem.loginBeginTime).format("YYYY-MM-DD HH:mm:ss") : '',
                loginEndTime: timeItem.loginEndTime ? moment(timeItem.loginEndTime).format("YYYY-MM-DD HH:mm:ss") : ''
              };
            });
          }
          return {
            ...item,
            loginBeginTime: item.loginBeginTime ? moment(item.loginBeginTime).format("YYYY-MM-DD HH:mm:ss") : '',
            loginEndTime: item.loginEndTime ? moment(item.loginEndTime).format("YYYY-MM-DD HH:mm:ss") : '',
          };
        });
        this.loading = false;
      }).catch(error => {
        this.loading = false;
        console.error('加载数据失败:', error);
      });
    },
    handleEdit(row) {
      //编辑 页面
      this.$router.push({
        path: '/detailRoute',
        query: {
          id: row.id,
          componentName: 'userAdd',
          routerTitle: '用户编辑'
        }
      });
    },
    handleAdd() {
      //新增 页面
      this.$router.push({
        path: '/detailRoute',
        query: {
          componentName: 'userAdd',
          routerTitle: '用户新增'
        }
      });
    },
  }
};
